/// <summary>
/// PaffH 19.08.25
/// </summary>
/// <param name = "_element">FormRun</param>
/// <returns>NDXKBVBuildingProjectSearchForm</returns>
public static NDXKBVBuildingProjectSearchForm NewFromForm(FormRun _element)
{
    NDXKBVBuildingProjectSearchForm form;
    form = new NDXKBVBuildingProjectSearchForm();
    form.InitFromFormRun(_element);
    return form;
}

/// <summary>
/// PaffH 19.08.25
/// last modified: PaffH 04.09.25
/// </summary>
/// <param name = "_contract">NDXBVSearchContract</param>
/// <param name = "_filterOption">int</param>
public void fillFormValuesFromContract(NDXBVSearchContract _contract, int _filterOption = 0)
{
    if (thisFormRun is NDXKBVBuildingProjectSearchI)
    {
        NDXKBVBuildingProjectSearchI nDXKBVBuildingProjectSearchI = thisFormRun as NDXKBVBuildingProjectSearchI;
        if (_contract.parmBuildingProjectId())
        {
            if (_filterOption == 0)
            {
                nDXKBVBuildingProjectSearchI.editBuildingProjectId(true, _contract.parmBuildingProjectId());
                nDXKBVBuildingProjectSearchI.editOperatorBuildingProjectId(true, AVASqlOperator::Like);
            }
            if (_filterOption == 1)
            {
                nDXKBVBuildingProjectSearchI.editBuildingProjectId(true, '');
                nDXKBVBuildingProjectSearchI.editOperatorBuildingProjectId(true, AVASqlOperator::Is);
            }

        }
        if (_contract.parmSubject())
        {
            if (_filterOption == 0)
            {
                nDXKBVBuildingProjectSearchI.editSubject(true, _contract.parmSubject());
                nDXKBVBuildingProjectSearchI.editOperatorSubject(true, _contract.parmOperatorSubject());
            }
            if (_filterOption == 1)
            {
                nDXKBVBuildingProjectSearchI.editSubject(true, '');
                nDXKBVBuildingProjectSearchI.editOperatorSubject(true, AVASqlOperator::Is);
            }
        }
        if (_contract.parmCity())
        {
            if (_filterOption == 0)
            {
                nDXKBVBuildingProjectSearchI.editCity(true, _contract.parmCity());
                nDXKBVBuildingProjectSearchI.editOperatorCity(true, _contract.parmOperatorCity());
            }
            if (_filterOption == 1)
            {
                nDXKBVBuildingProjectSearchI.editCity(true, '');
                nDXKBVBuildingProjectSearchI.editOperatorCity(true, AVASqlOperator::Is);
            }
        }

        if (_contract.parmContactName())
        {
            if (_filterOption == 0 || _filterOption == 1)
            {
                nDXKBVBuildingProjectSearchI.editContactName(true, _contract.parmContactName());
                nDXKBVBuildingProjectSearchI.editOperatorContact(true, _contract.parmOperatorContact());
            }
        }
        if (_contract.parmPartyName())
        {
            if (_filterOption == 0 || _filterOption == 1)
            {
                nDXKBVBuildingProjectSearchI.editPartyName(true, _contract.parmPartyName());
                nDXKBVBuildingProjectSearchI.editOperatorParty(true, AVASqlOperator::Like);
            }
        }
    }
}
